    slide("b-handoff", "Hand off to learners", ["Give every learner the items on the right, each in a private message.", "Never post TAPs publicly."], "Each learner can reach the agent and knows who supports them.", snip(admin[2], "8.2")),
    slide("b-cleanup", "Clean up after class", ["Close the accounts using the **last step of the Module 1 Instructor guide**.", "Run the first command to preview the Azure removal.", "After you save any required evidence, run the second command."], "Account access, Azure resources, the model role, app grants, licenses and evidence each have a recorded done or blocked outcome. The existing model is kept; remove registered agent, blueprint and apps in Entra only with approval.", snip(admin[2], "8.3"))
